const siteOf = (row) => get(row.employee_extension_data, 'worksite', '');
const ground = (row) => get(row.employee_extension_data, 'exit_facts.lsa_termination_ground', 'OTHER');
const leavers = contracts.filter((row) => {
	if (row.status !== 'SEALED') return false;
	if (!ctx.lookup.grounds.includes(ground(row))) return false;
	if (get(row.employee_extension_data, 'term_facts.fixed_term_category', null) != null) return false;
	const to = on(row, 'effective_range.to');
	if (to == null) return false;
	if (!(to >= add_days(exit, -ctx.lookup.window_days))) return false;
	return to <= exit;
});
const staff = contracts.filter((row) => {
	if (row.status !== 'SEALED') return false;
	if (!(on(row, 'effective_range.from') <= exit)) return false;
	const to = on(row, 'effective_range.to');
	return to == null || to >= exit;
});
const siteStaff = staff.filter((row) => siteOf(row) === site).length;
const siteLeavers = leavers.filter((row) => siteOf(row) === site);
const siteDay = siteLeavers.filter((row) => on(row, 'effective_range.to') === exit).length;
const rolling =
	siteStaff < ctx.lookup.small_site_upper ? ctx.lookup.small_site_count
	: siteStaff < ctx.lookup.medium_site_upper ? Math.floor(siteStaff / ctx.lookup.medium_site_divisor)
	: siteStaff < ctx.lookup.large_site_upper ? Math.floor(siteStaff / ctx.lookup.large_site_divisor)
	: Math.floor(siteStaff / ctx.lookup.largest_site_divisor);
if (siteLeavers.length > rolling) return true;
const daily =
	siteStaff < ctx.lookup.medium_site_upper ? ctx.lookup.medium_site_daily
	: siteStaff < ctx.lookup.large_site_upper ? ctx.lookup.large_site_daily
	: ctx.lookup.largest_site_daily;
if (siteStaff >= ctx.lookup.small_site_upper && siteDay > daily) return true;
if (leavers.length > ctx.lookup.entity_rolling) return true;
const entityDay = leavers.filter((row) => on(row, 'effective_range.to') === exit).length;
return entityDay > ctx.lookup.entity_daily;

